function validate([answerKey, k]) {
  if (typeof answerKey !== 'string' || answerKey.length < 1 || answerKey.length > 50000) return 'answerKey needs 1 to 50000 characters.';
  if (!/^[TF]+$/.test(answerKey)) return "answerKey contains only 'T' and 'F'.";
  if (!Number.isInteger(k) || k < 1 || k > answerKey.length) return 'k is between 1 and the length of answerKey.';
  return null;
}

