function maxConsecutiveAnswers(answerKey, k) {
  const count = new Map([['T', 0], ['F', 0]]);
  let left = 0;
  let best = 0;
  for (let right = 0; right < answerKey.length; right++) {
    count.set(answerKey[right], count.get(answerKey[right]) + 1);
    while (Math.min(count.get('T'), count.get('F')) > k) {
      count.set(answerKey[left], count.get(answerKey[left]) - 1);
      left++;
    }
    best = Math.max(best, right - left + 1);
  }
  return best;
}

