function maxConsecutiveAnswers(answerKey, k) {
  // Try every block: it can be made uniform if the rarer answer inside it appears at most k times.
  let answer = 0;
  for (let i = 0; i < answerKey.length; i++) {
    let t = 0, f = 0;
    for (let j = i; j < answerKey.length; j++) {
      if (answerKey[j] === 'T') t++; else f++;
      if (Math.min(t, f) <= k) answer = Math.max(answer, j - i + 1);
    }
  }
  return answer;
}

