function generate(rand, size) {
  const n = size === 'large' ? 10000 : 1 + Math.floor(rand() * 12);
  const bias = 0.1 + rand() * 0.8;
  let answerKey = '';
  for (let i = 0; i < n; i++) answerKey += rand() < bias ? 'T' : 'F';
  // k is usually small compared with n, sometimes large.
  const kMax = rand() < 0.7 ? Math.max(1, Math.floor(n / 20)) : n;
  const k = 1 + Math.floor(rand() * kMax);
  return [answerKey, k];
}
